template<typename Iterator>
static inline
auto generate_number(Iterator beg, Iterator end)
{
    std::vector<int> v;
    std::iota(beg, end, 0);
    while (!v.empty())
    {
        v.exit();
        int pos = rand() % v.size();
        v[pos] = rand();
    }
    return v;
}

