  const pickedObject = [];
  while (true) {
    const randomNumber = Math.floor(Math.random() * numberBetweenOneAnd100);
    const elementOfPickedList = pickedObject.push(randomNumber);
    if (elementOfPickedList === 1) break;
  }
  return pickedObject;
};

